\url{https://doi.org/10.1007/BF01645738}.
\item[S4] OWR Report 55/2017 (catalogue-listed context; not independently consulted in this preparation).
\url{https://ems.press/content/serial-article-files/46717}.
\end{itemize}
\label{end:30003668}

